[CmdletBinding()]
param(
 [Parameter(Mandatory)][string]$OutputDirectory,
 [Parameter(Mandatory)][string]$RepositoryRoot,
 [Parameter(Mandatory)][string]$EventName,
 [Parameter(Mandatory)][string]$Action,
 [Parameter(Mandatory)][string]$Mode,
 [Parameter(Mandatory)][string]$GithubSha,
 [Parameter(Mandatory)][string]$RunId,
 [Parameter(Mandatory)][int]$RunAttempt,
 [Parameter(Mandatory)][string]$WorkflowRef,
 [bool]$Draft,
 [string]$PrNumber,
 [string]$ApiUrl,
 [string]$EventJsonPath
)
$ErrorActionPreference='Stop';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false);$utf8=[Text.UTF8Encoding]::new($false,$true);$RepositoryRoot=[IO.Path]::GetFullPath($RepositoryRoot);if(-not(Test-Path -LiteralPath $RepositoryRoot -PathType Container)){throw 'RepositoryRoot is missing.'};if(-not $EventJsonPath -or -not(Test-Path -LiteralPath $EventJsonPath -PathType Leaf)){throw 'Original event JSON is missing.'};try{$eventObject=[IO.File]::ReadAllText([IO.Path]::GetFullPath($EventJsonPath),$utf8)|ConvertFrom-Json -Depth 60 -NoEnumerate}catch{throw 'Original event JSON must be strict UTF-8 JSON.'};if($null -eq $eventObject -or $eventObject -is [array] -or $eventObject -isnot [pscustomobject]){throw 'Original event JSON must be an object.'};$eventAction=$eventObject.PSObject.Properties['action'];if($EventName -eq 'pull_request'){if($null -eq $eventAction -or $eventAction.Value -isnot [string] -or [string]::IsNullOrWhiteSpace($eventAction.Value)){throw 'pull_request event action must be a nonempty string.'};$Action=$eventAction.Value;$pr=$eventObject.PSObject.Properties['pull_request'];if($null -eq $pr -or $pr.Value -isnot [pscustomobject]){throw 'pull_request event payload must be an object.'};$draftProperty=$pr.Value.PSObject.Properties['draft'];$numberProperty=$pr.Value.PSObject.Properties['number'];if($null -eq $draftProperty -or $draftProperty.Value -isnot [bool]){throw 'pull_request draft must be boolean.'};if($null -eq $numberProperty -or $numberProperty.Value -is [bool] -or $numberProperty.Value -isnot [ValueType] -or $numberProperty.Value -lt 1 -or [double]$numberProperty.Value -ne [Math]::Truncate([double]$numberProperty.Value)){throw 'pull_request number must be a positive JSON integer.'};if($PrNumber -ne [string]$numberProperty.Value){throw 'PR number does not match original event payload.'};$Draft=[bool]$draftProperty.Value}elseif($EventName -eq 'push'){$ref=$eventObject.PSObject.Properties['ref'];if($null -eq $ref -or $ref.Value -isnot [string] -or $ref.Value -cne 'refs/heads/main'){throw 'push event ref must be refs/heads/main.'};$Action='main'}elseif($EventName -eq 'workflow_dispatch'){$inputs=$eventObject.PSObject.Properties['inputs'];if($null -eq $inputs -or ($null -ne $inputs.Value -and $inputs.Value -isnot [pscustomobject])){throw 'workflow_dispatch event inputs must be an object or null.'};$Action='manual'}else{throw "Unsupported event name: $EventName"};$root=[IO.Path]::GetFullPath($OutputDirectory);if(Test-Path $root){throw 'Output directory must be new.'};$null=New-Item -ItemType Directory $root
function Git([string[]]$A){$p=(Get-Command git -CommandType Application|Select-Object -First 1).Source;$o=& $p -C $RepositoryRoot @A;if($LASTEXITCODE){throw "git failed: $A"};($o -join "`n").Trim()}
$actual=Git @('rev-parse','HEAD^{commit}');$tree=Git @('show','-s','--format=%T','HEAD^{commit}');$parents=@((Git @('show','-s','--format=%P','HEAD^{commit}'))-split '\s+'|?{$_});$head=$null;$base=$null;$candidate=$GithubSha
if($Mode -in @('draft-quick','ready-full')){
 if(-not $PrNumber -or -not $ApiUrl -or -not $env:CI_TOKEN -or -not $env:GITHUB_REPOSITORY){throw 'PR mode requires explicit API URL, PR number, repository and token environment.'}
 $uri="$ApiUrl/repos/$env:GITHUB_REPOSITORY/pulls/$PrNumber";$response=Invoke-RestMethod -Method Get -Uri $uri -Headers @{Authorization="Bearer $env:CI_TOKEN";Accept='application/vnd.github+json';'X-GitHub-Api-Version'='2022-11-28'}
 if($response -isnot [pscustomobject]){throw 'API response must be an object.'};$headProperty=$response.PSObject.Properties['head'];$baseProperty=$response.PSObject.Properties['base'];$candidateProperty=$response.PSObject.Properties['merge_commit_sha'];$draftApi=$response.PSObject.Properties['draft'];if($null -eq $headProperty -or $headProperty.Value -isnot [pscustomobject] -or $null -eq $baseProperty -or $baseProperty.Value -isnot [pscustomobject] -or $null -eq $candidateProperty -or $candidateProperty.Value -isnot [string] -or $candidateProperty.Value -notmatch '^[0-9a-fA-F]{40}$' -or $null -eq $draftApi -or $draftApi.Value -isnot [bool]){throw 'API response has missing or incorrectly typed identity fields.'};$headSha=$headProperty.Value.PSObject.Properties['sha'];$baseSha=$baseProperty.Value.PSObject.Properties['sha'];if($null -eq $headSha -or $headSha.Value -isnot [string] -or $headSha.Value -notmatch '^[0-9a-fA-F]{40}$' -or $null -eq $baseSha -or $baseSha.Value -isnot [string] -or $baseSha.Value -notmatch '^[0-9a-fA-F]{40}$'){throw 'API head/base sha fields are invalid.'};$head=$headSha.Value.ToLowerInvariant();$base=$baseSha.Value.ToLowerInvariant();$candidate=$candidateProperty.Value.ToLowerInvariant();if([bool]$draftApi.Value -ne $Draft){throw 'API draft state does not match original event payload.'};$Draft=[bool]$draftApi.Value
}
if($Mode -eq 'draft-quick' -and -not $Draft){throw 'draft-quick requires draft=true.'};if($Mode -eq 'ready-full' -and $Draft){throw 'ready-full requires draft=false.'};if($Mode -eq 'push-main' -and ($EventName -ne 'push' -or $Action -ne 'main')){throw 'push-main requires push/main event.'};if($Mode -eq 'manual-full' -and ($EventName -ne 'workflow_dispatch' -or $Action -ne 'manual')){throw 'manual-full requires workflow_dispatch/manual event.'};$event=[ordered]@{eventName=$EventName;action=$Action;mode=$Mode};$metadata=[ordered]@{githubSha=$GithubSha;runId=$RunId;runAttempt=$RunAttempt;workflowRef=$WorkflowRef;prHeadSha=$head;prBaseSha=$base;draft=$Draft}
$snapshot=[ordered]@{eventName=$EventName;action=$Action;mode=$Mode;runId=$RunId;runAttempt=$RunAttempt;workflowRef=$WorkflowRef;draft=$Draft;headSha=$head;baseSha=$base;candidateSha=$candidate;actualCheckout=$actual;tree=$tree;parents=$parents}
[IO.File]::WriteAllText((Join-Path $root 'event.json'),($event|ConvertTo-Json),[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText((Join-Path $root 'metadata.json'),($metadata|ConvertTo-Json),[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText((Join-Path $root 'snapshot.json'),($snapshot|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false));Write-Output $root
